def compute(vars):
    december_purchase = vars["v1"]
    january_purchase = vars["v2"]

    if january_purchase == 0:
        return None

    value = december_purchase / january_purchase
    return {
        "value": value,
        "trace": {
            "december_purchase": december_purchase,
            "january_purchase": january_purchase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
